import{z as n,x as o,o as B,c as d,q as t,j as r,D as a,d as l,s as i,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"安全与有用数据的配比","description":"","frontmatter":{"title":"安全与有用数据的配比","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ade-safety-helpful-mix.md","filePath":"llm/ade-safety-helpful-mix.md","lastUpdated":1791063341000}'),C={name:"llm/ade-safety-helpful-mix.md"};function p(m,E,D,F,f,h){const A=o("Mermaid");return B(),d("div",null,[E[2]||(E[2]=t('<h1 id="安全与有用数据的配比" tabindex="-1">安全与有用数据的配比 <a class="header-anchor" href="#安全与有用数据的配比" aria-label="Permalink to &quot;安全与有用数据的配比&quot;">​</a></h1><div class="epigraph"><p>安全与有用不是两个可以各自最大化再相加的目标；配比是把帕累托上的工作点，写进数据卡的那个数。</p><footer>—— 据 Touvron 等 Llama 2, 2023 与 Bai et al., 2022 整理</footer></div><p><a href="/llm/ade-dedup-cleaning">上一课</a>收在「每条丢弃规则都是一次无声的再配比」；本课正面写配比，只写安全与有用这一条轴。配比的三轴总论（来源、域、难度）与分域下限验收，<a href="/llm/rm-data-mix">偏好数据的配比与域覆盖</a>已经讲过，口径直接搬过来用；本课补的是这条轴特有的张力。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>这条轴上配比失误的两种形态都见过：安全池不足，危害配合率下不来；安全池过重或只教说不，越权拒绝率上去，能力损失摊进对齐税——<a href="/llm/aeval-alignment-tax">对齐税的测量</a>的分层消融显示税集中在创意写作、长文这些敏感域。麻烦在于两类数据不对等：安全边界集中，拒答短语与危害关键词附近的表面特征，样本效率高；有用边界弥散，覆盖全部意图域，靠覆盖不靠权重。一个全局占比数既不反映两边的样本效率，也不反映产品要的工作点。而「全拒赢榜」的作弊在数据侧同样成立——只堆安全数据，基准分数好看，产品不可用；<a href="/llm/aeval-safety-benchmark-design">安全基准的设计原则</a>用成对指标封的是评测侧的同一个洞。</p><p><span class="marginnote">「危害配合率」是模型被攻破、顺着有害请求作答的比例；「越权拒绝率」是反过来把正常请求也当有害拒掉的比例。好模型要两个都低：既不当帮凶，也不当惊弓之鸟——成对报这两个数，就是为了不让一头掩盖另一头。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>配比按三步走。第一步分域记账：安全池内部按「危害类别 × 攻击族」切——红队覆盖矩阵的同一张表；有用池按意图分类法切。占比定在格子上，不在池上定。第二步分域下限验收：沿用配比课的口径，验收对象是各域下限，不是加权平均；危害每类、意图每类各设下限。第三步工作点读数：越权率与危害配合率成对报（<a href="/llm/aeval-overrefusal-metric">越权行为的度量</a>的主图），在帕累托上先指定工作点再回头调比；每轮迭代后用对齐税的分层消融定位税落在哪层——权重、提示还是门，把「安全多了」与「安全做法糙了」分开。对照对计入有用侧：它们同时服务两个池。</p>',8)),(B(),r(s,null,{default:a(()=>[i(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SAFE%5B%22%E5%AE%89%E5%85%A8%E6%B1%A0%EF%BC%9A%E5%8D%B1%E5%AE%B3%E7%B1%BB%E5%88%AB%C3%97%E6%94%BB%E5%87%BB%E6%97%8F%22%5D%20--%3E%20GRID%5B%22%E5%88%86%E5%9F%9F%E8%AE%B0%E8%B4%A6%20%2B%20%E5%90%84%E5%9F%9F%E4%B8%8B%E9%99%90%22%5D%0A%20%20HELP%5B%22%E6%9C%89%E7%94%A8%E6%B1%A0%EF%BC%9A%E6%84%8F%E5%9B%BE%C3%97%E9%9A%BE%E5%BA%A6%22%5D%20--%3E%20GRID%0A%20%20GRID%20--%3E%20TRAIN%5B%22%E8%AE%AD%E7%BB%83%22%5D%0A%20%20TRAIN%20--%3E%20M%5B%22%E8%AF%BB%E6%95%B0%EF%BC%9A%E8%B6%8A%E6%9D%83%E7%8E%87%20%C3%97%20%E5%8D%B1%E5%AE%B3%E9%85%8D%E5%90%88%E7%8E%87%20%C3%97%20%E7%A8%8E%E5%89%96%E9%9D%A2%22%5D%0A%20%20M%20--%3E%7C%22%E5%B7%A5%E4%BD%9C%E7%82%B9%E5%81%8F%E4%BF%9D%E5%AE%88%EF%BC%9A%E8%A1%A5%E6%9C%89%E7%94%A8%20%2F%20%E8%A1%A5%E5%AF%B9%E7%85%A7%22%7C%20ADJ%5B%22%E8%B0%83%E6%AF%94%22%5D%0A%20%20M%20--%3E%7C%22%E5%B7%A5%E4%BD%9C%E7%82%B9%E5%81%8F%E6%BF%80%E8%BF%9B%EF%BC%9A%E8%A1%A5%E8%BE%B9%E7%95%8C%E5%AF%B9%22%7C%20ADJ%0A%20%20ADJ%20--%3E%20GRID%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"为什么配比是工作点不是权重：混训损失是两类对比结构之和，RM 容量有限，梯度竞争决定哪类边界先被拟合。安全边界特征集中、便宜，权重稍给就成形；权重给过头，容量就从有用侧被吸走——所以配比失误的表现是某域塌陷而全局均值不动，配比课的机制原话在这里原样生效。工作点的语义由此清晰：占比决定的是容量分配的优先序，工作点决定的是停在哪；前者是手段，后者是产品决策，两件事不能互相替代，也不能用一个数同时管两件事。",-1)),E[5]||(E[5]=e("p",null,"容量竞争如何让「某域塌陷而均值不动」，机制上是这样一串因果：",-1)),(B(),r(s,null,{default:a(()=>[i(A,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20CAP%5B%22RM%20%E6%9C%89%E9%99%90%E5%AE%B9%E9%87%8F%22%5D%20--%3E%7C%22%E5%AE%89%E5%85%A8%E8%BE%B9%E7%95%8C%EF%BC%9A%E7%89%B9%E5%BE%81%E9%9B%86%E4%B8%AD%EF%BC%8C%E5%B0%91%E9%87%8F%E6%A0%B7%E6%9C%AC%E6%88%90%E5%BD%A2%22%7C%20SB%5B%22%E5%BF%AB%E9%80%9F%E5%8D%A0%E7%94%A8%E5%AE%B9%E9%87%8F%22%5D%0A%20%20CAP%20--%3E%7C%22%E6%9C%89%E7%94%A8%E8%BE%B9%E7%95%8C%EF%BC%9A%E7%89%B9%E5%BE%81%E5%BC%A5%E6%95%A3%EF%BC%8C%E9%9D%A0%E8%A6%86%E7%9B%96%22%7C%20HB%5B%22%E7%BC%93%E6%85%A2%E9%93%BA%E5%BC%80%22%5D%0A%20%20SB%20--%3E%7C%22%E5%AE%89%E5%85%A8%E6%9D%83%E9%87%8D%E7%BB%99%E8%BF%87%E5%A4%B4%22%7C%20STEAL%5B%22%E5%AE%B9%E9%87%8F%E4%BB%8E%E6%9C%89%E7%94%A8%E4%BE%A7%E8%A2%AB%E5%90%B8%E8%B5%B0%22%5D%0A%20%20STEAL%20--%3E%20SINK%5B%22%E5%88%9B%E6%84%8F%E5%86%99%E4%BD%9C%20%2F%20%E9%95%BF%E6%96%87%E5%9F%9F%E5%A1%8C%E9%99%B7%22%5D%0A%20%20MEAN%5B%22%E5%85%A8%E5%B1%80%E5%9D%87%E5%80%BC%E5%87%A0%E4%B9%8E%E4%B8%8D%E5%8A%A8%22%5D%20-.-%3E%7C%22%E6%8E%A9%E7%9B%96%22%7C%20SINK%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p><span class="marginnote">把 RM 的容量想成一块固定大小的黑板：安全边界笔画少，几笔就画清楚；有用边界要画满整面墙。安全内容写得太多，黑板就没地方写有用的部分——而且在不重训细看的前提下，平均分上看不出哪块被挤掉了。</span></p><p><span class="marginnote">Llama 2 约 141 万条比较对中安全与有用几乎各半。「各半」不是道德表态而是样本效率的账：安全边界特征集中、便宜，有用边界要覆盖、贵；两边在「边界成形」上的成本接近时，池子大小才接近对半。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>配比不解决单条质量，那是上一课的账。帕累托前沿随基座与解码配置移动，工作点每轮重估——所以配比是下一课轮次策略的输入，不是常量。对齐税的读数必须走因果消融，能力榜上的前后差值不算税。政策改版会移动「危害类别」的定义本身，安全池要按版本重映射——红队课的版本绑定在这里收利息。</p><p><span class="marginnote">「对齐税」指为了安全付出的能力代价：安全做得越多，写作、长文这类能力掉得越多。测它要靠「因果消融」——只换掉安全数据、其他一切不动再重训一次，前后分差才是税；只拿两个版本模型的榜单相减，里面混着无数别的改动，不算数。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>配比失误两形态：安全不足则危害配合率下不来；安全过重则越权拒绝与对齐税上去。</li><li>占比定在格子上（危害类别 × 攻击族、意图 × 难度），验收对象是各域下限而非加权平均。</li><li>越权率与危害配合率成对报，先指定工作点再调比；税走分层消融定位。</li><li>机制是梯度竞争与样本效率差：安全边界便宜，有用边界靠覆盖。</li><li>出处：Touvron 等 Llama 2，2023；Bai et al., 2022；配比与分域下限口径见配比课。</li></ul>',7))])}const c=n(C,[["render",p]]);export{_ as __pageData,c as default};
